-- 1) 행 수
SELECT COUNT(*) FROM t;
-- 2) 컬럼별 결측 비율
SELECT AVG(CASE WHEN amount IS NULL THEN 1 ELSE 0 END) FROM t;
-- 3) 유일값 수 (id 인데 중복? 범주인데 1000종?)
SELECT COUNT(DISTINCT user_id), COUNT(DISTINCT country) FROM t;
-- 4) 최소·최대·분포 (음수 나이·미래 날짜·0원 결제)
SELECT MIN(age), MAX(age), MIN(signup_at), MAX(signup_at) FROM t;
